{"content":"#!/usr/bin/env node
/**
 * 🤖 WhatsApp Personal Assistant — دستیار هوشمند شخصی واتساپ
 * Connected to AI (GLM via 9router). Manages tasks, reminders, shopping lists,
 * daily reports, natural-language parsing, smart memory.
 *
 * Features:
 *  - Smart chat with AI
 *  - Task capture via natural language
 *  - Scheduled reminders (one-off + recurring daily/weekly)
 *  - Smart memory / habit learning
 *  - Todo list with done-marking
 *  - Morning daily report + evening summary
 *  - Shopping list
 *  - Text summarization & translation
 *  - Automatic data backup
 */

const fs = require('fs');
const path = require('path');
const { default: makeWASocket, useMultiFileAuthState, DisconnectReason, fetchLatestBaileysVersion } = require('@whiskeysockets/baileys');
const QR = require('qrcode-terminal');
const cron = require('node-cron');
const OpenAI = require('openai');

// ─── Config ─────────────────────────────────────────────────────────────
const DATA_DIR = __dirname;
const STORE_FILE = path.join(DATA_DIR, 'data.json');
const SESSION_DIR = path.join(DATA_DIR, 'auth');

const OPENAI_KEY = process.env.OPENAI_API_KEY || '';
const OPENAI_BASE = process.env.OPENAI_BASE_URL || 'https://9router-production-d365.up.railway.app/v1';
const AI_MODEL = process.env.AI_MODEL || 'glm-5.3-flash';

const openai = new OpenAI({ apiKey: *** baseURL: OPENAI_BASE });

// ─── Persistent store ─────────────────────────────────────────────────────
function loadStore() {
  try {
    return JSON.parse(fs.readFileSync(STORE_FILE, 'utf8'));
  } catch {
    return { users: {}, tasks: [], reminders: [], shopping: [], memories: {}, summaries: [] };
  }
}
function saveStore(s) {
  fs.writeFileSync(STORE_FILE, JSON.stringify(s, null, 2));
}
let STORE = loadStore();

// ─── AI helpers ───────────────────────────────────────────────────────────
async function aiChat(systemPrompt, userText, history = []) {
  try {
    const messages = [
      { role: 'system', content: systemPrompt },
      ...history,
      { role: 'user', content: userText },
    ];
    const r = await openai.chat.completions.create({
      model: AI_MODEL,
      messages,
      temperature: 0.7,
      max_tokens: 800,
    });
    return r.choices[0].message.content.trim();
  } catch (e) {
    console.error('AI error:', e.message);
    return '⚠️ الان نتونستم به هوش‌مصنوعی وصل بشم. لطفاً چند لحظه دیگه امتحان کن یا دستور رو مستقیم بزن.';
  }
}

// System prompt for the personal assistant persona
const ASSISTANT_SYS = `تو یک دستیار شخصی هوشمند فارسی‌زبان روی واتساپ هستی.
وظایف: مدیریت کارها، یادآوری‌ها، لیست خرید، گزارش روزانه، خلاصه‌سازی و ترجمه.
لحن صمیمی ولی مفید باش. پاسخ‌ها کوتاه و کاربردی. از ایموجی مناسب استفاده کن.
اگر درخواست نیاز به ثبت در سیستم دارد، ابتدا انجام بده و بعد تأیید بده.`;

// ─── Command parsing via AI ────────────────────────────────────────────────
async function parseCommand(text, jid) {
  const sys = `تحلیل کن متن کاربر و یکی از دستورهای زیر را برگردان به صورت JSON خام (فقط JSON، بدون توضیح):
{"action":"task_add","title":"...","due":"ISO یا null","priority":"low|normal|high"}
{"action":"task_list"}
{"action":"task_done","id":N}
{"action":"reminder_add","text":"...","when":"ISO datetime یا null","repeat":"none|daily|weekly"}
{"action":"reminder_list"}
{"action":"shopping_add","item":"..."}
{"action":"shopping_list"}
{"action":"shopping_remove","item":"..."}
{"action":"summary","text":"..."}
{"action":"translate","text":"...","to":"en|fa"}
{"action":"chat"}
اگر متن فقط گفتگوست action=chat باشد.
متن کاربر: """${text}"""`;
  try {
    const r = await openai.chat.completions.create({
      model: AI_MODEL,
      messages: [{ role: 'system', content: sys }, { role: 'user', content: text }],
      temperature: 0.2,
      max_tokens: 300,
    });
    let raw = r.choices[0].message.content.trim();
    raw = raw.replace(/^```json/i, '').replace(/```$/i, '').trim();
    return JSON.parse(raw);
  } catch (e) {
    return { action: 'chat' };
  }
}

// ─── Task / reminder / shopping logic ─────────────────────────────────────
function nextTaskId() {
  return STORE.tasks.reduce((m, t) => Math.max(m, t.id), 0) + 1;
}

async function handleParsed(cmd, jid, originalText) {
  switch (cmd.action) {
    case 'task_add': {
      const t = { id: nextTaskId(), title: cmd.title || originalText, done: false, due: cmd.due || null, priority: cmd.priority || 'normal', created: Date.now() };
      STORE.tasks.push(t);
      saveStore(STORE);
      return `✅ کار ثبت شد:\n📌 ${t.title}${t.due ? `\n⏰ موعد: ${new Date(t.due).toLocaleString('fa-IR')}` : ''}`;
    }
    case 'task_list': {
      const open = STORE.tasks.filter(t => !t.done);
      if (!open.length) return '📭 هیچ کار بازی نداری.';
      return '📋 کارهای باز:\n' + open.map(t => `${t.id}. ${t.done ? '☑️' : '🔲'} ${t.title}`).join('\n');
    }
    case 'task_done': {
      const t = STORE.tasks.find(t => t.id === cmd.id);
      if (!t) return '❌ کار با این شماره پیدا نشد.';
      t.done = true; saveStore(STORE);
      return `☑️ انجام شد: ${t.title}`;
    }
    case 'reminder_add': {
      const rem = { id: Date.now(), text: cmd.text || originalText, when: cmd.when || null, repeat: cmd.repeat || 'none', jid };
      STORE.reminders.push(rem); saveStore(STORE);
      scheduleReminder(rem);
      const whenStr = cmd.when ? new Date(cmd.when).toLocaleString('fa-IR') : 'زود';
      return `⏰ یادآوری تنظیم شد:\n🔔 ${rem.text}\n🗓 ${whenStr}${cmd.repeat !== 'none' ? ` (تکرار: ${cmd.repeat === 'daily' ? 'روزانه' : 'هفتگی'})` : ''}`;
    }
    case 'reminder_list': {
      if (!STORE.reminders.length) return '🔕 یادآوری فعالی نداری.';
      return '⏰ یادآوری‌ها:\n' + STORE.reminders.map(r => `🔔 ${r.text} — ${r.when ? new Date(r.when).toLocaleString('fa-IR') : 'زود'}`).join('\n');
    }
    case 'shopping_add': {
      STORE.shopping.push(cmd.item); saveStore(STORE);
      return `🛒 اضافه شد به لیست خرید: ${cmd.item}`;
    }
    case 'shopping_list': {
      if (!STORE.shopping.length) return '🛒 لیست خرید خالیه.';
      return '🛒 لیست خرید:\n' + STORE.shopping.map((i, n) => `${n + 1}. ${i}`).join('\n');
    }
    case 'shopping_remove': {
      const before = STORE.shopping.length;
      STORE.shopping = STORE.shopping.filter(i => i !== cmd.item);
      saveStore(STORE);
      return before !== STORE.shopping.length ? `🗑 حذف شد: ${cmd.item}` : '❌ این مورد تو لیست نبود.';
    }
    case 'summary': {
      const s = await aiChat('متن زیر را در ۳ خط خلاصه کن (فارسی):', cmd.text || originalText);
      return `📝 خلاصه:\n${s}`;
    }
    case 'translate': {
      const to = cmd.to === 'en' ? 'انگلیسی' : 'فارسی';
      const s = await aiChat(`متن را به ${to} ترجمه کن:`, cmd.text || originalText);
      return `🌐 ترجمه (${to}):\n${s}`;
    }
    default:
      return await aiChat(ASSISTANT_SYS, originalText, getHistory(jid));
  }
}

function getHistory(jid) {
  const u = STORE.users[jid] || [];
  return u.slice(-10);
}
function pushHistory(jid, role, text) {
  if (!STORE.users[jid]) STORE.users[jid] = [];
  STORE.users[jid].push({ role, content: text });
  if (STORE.users[jid].length > 30) STORE.users[jid].shift();
  saveStore(STORE);
}

// ─── Reminders scheduling ─────────────────────────────────────────────────
function scheduleReminder(rem) {
  if (!rem.when) return;
  const fire = new Date(rem.when);
  const delay = fire.getTime() - Date.now();
  if (delay > 0) {
    setTimeout(async () => {
      await sendReminder(rem);
      if (rem.repeat === 'daily') {
        rem.when = new Date(fire.getTime() + 86400000).toISOString();
        saveStore(STORE); scheduleReminder(rem);
      } else if (rem.repeat === 'weekly') {
        rem.when = new Date(fire.getTime() + 7 * 86400000).toISOString();
        saveStore(STORE); scheduleReminder(rem);
      }
    }, delay);
  }
}
async function sendReminder(rem) {
  try {
    await sock.sendMessage(rem.jid, { text: `⏰ یادآوری:\n🔔 ${rem.text}` });
  } catch (e) { console.error('reminder send err', e.message); }
}
// re-schedule persisted reminders on startup
STORE.reminders.forEach(scheduleReminder);

// ─── Daily report (09:00) & evening summary (22:00) ───────────────────────
cron.schedule('0 9 * * *', async () => {
  const open = STORE.tasks.filter(t => !t.done);
  const msg = `☀️ گزارش صبح:\n📋 ${open.length} کار باز\n${open.slice(0, 5).map(t => `• ${t.title}`).join('\n')}\n🛒 لیست خرید: ${STORE.shopping.length} مورد`;
  broadcast(msg);
});
cron.schedule('0 22 * * *', async () => {
  const doneToday = STORE.tasks.filter(t => t.done);
  const msg = `🌙 جمع‌بندی شب:\n✅ انجام‌شده: ${doneToday.length}\n📋 باز: ${STORE.tasks.filter(t => !t.done).length}`;
  broadcast(msg);
});
function broadcast(text) {
  const jids = new Set([...STORE.reminders.map(r => r.jid), ...Object.keys(STORE.users)]);
  jids.forEach(j => sock.sendMessage(j, { text }).catch(() => {}));
}

// ─── Automatic backup ──────────────────────────────────────────────────────
cron.schedule('0 */6 * * *', () => {
  try {
    const bak = path.join(DATA_DIR, `data.backup.${Date.now()}.json`);
    fs.copyFileSync(STORE_FILE, bak);
    // keep only last 5 backups
    const files = fs.readdirSync(DATA_DIR).filter(f => f.startsWith('data.backup.')).sort();
    while (files.length > 5) { fs.unlinkSync(path.join(DATA_DIR, files.shift())); }
    console.log('backup done');
  } catch (e) { console.error('backup err', e.message); }
});

// ─── WhatsApp connection ──────────────────────────────────────────────────
let sock;
async function connectToWhatsApp() {
  const { state, saveCreds } = await useMultiFileAuthState(SESSION_DIR);
  const { version } = await fetchLatestBaileysVersion();
  sock = makeWASocket({ version, auth: state, printQRInTerminal: false });

  sock.ev.on('connection.update', (update) => {
    const { connection, lastDisconnect, qr } = update;
    if (qr) {
      console.log('Scan this QR with WhatsApp:');
      QR.generate(qr, { small: true });
    }
    if (connection === 'close') {
      if (lastDisconnect?.error?.output?.statusCode !== DisconnectReason.loggedOut) {
        connectToWhatsApp();
      }
    }
    if (connection === 'open') console.log('✅ WhatsApp connected');
  });

  sock.ev.on('creds.update', saveCreds);

  sock.ev.on('messages.upsert', async ({ messages }) => {
    for (const m of messages) {
      if (!m.message || m.key.fromMe) continue;
      const jid = m.key.remoteJid;
      if (!jid.endsWith('@s.whatsapp.net')) continue; // only private chats
      const text = m.message.conversation || m.message.extendedTextMessage?.text || '';
      if (!text) continue;

      pushHistory(jid, 'user', text);
      const cmd = await parseCommand(text, jid);
      const reply = await handleParsed(cmd, jid, text);
      pushHistory(jid, 'assistant', reply);
      await sock.sendMessage(jid, { text: reply });
    }
  });
}

// expose sock for reminders/broadcast
global.sockRef = () => sock;
// re-bind sendReminder/broadcast to use live sock
async function sendReminder(rem) {
  const s = global.sockRef();
  if (s) await s.sendMessage(rem.jid, { text: `⏰ یادآوری:\n🔔 ${rem.text}` });
}
function broadcast(text) {
  const s = global.sockRef();
  const jids = new Set([...STORE.reminders.map(r => r.jid), ...Object.keys(STORE.users)]);
  jids.forEach(j => s && s.sendMessage(j, { text }).catch(() => {}));
}

connectToWhatsApp();
console.log('🤖 WhatsApp Assistant starting...');
